// s6_parser.js
function tokenize(expr) {
  const tokens = [];
  const regex = /(\d+(\.\d+)?|[+\-*/()])/g;
  let match;

  while ((match = regex.exec(expr)) !== null) {
    tokens.push(match[0]);
  }

  // Check if there are any remaining characters that aren't valid tokens
  const remaining = expr.replace(regex, '');
  if (remaining.trim() !== '') {
    throw new Error(`Invalid character: ${remaining.trim()[0]}`);
  }

  return tokens;
}

function evaluate(expr) {
  const tokens = tokenize(expr);

  // Convert to postfix notation using Shunting Yard algorithm
  const output = [];
  const operators = [];
  const precedence = { '+': 1, '-': 1, '*': 2, '/': 2 };

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];

    if (/^\d+(\.\d+)?$/.test(token)) {
      output.push(parseFloat(token));
    } else if (token === '(') {
      operators.push(token);
    } else if (token === ')') {
      while (operators.length > 0 && operators[operators.length - 1] !== '(') {
        output.push(operators.pop());
      }
      if (operators.length === 0) {
        throw new Error('Mismatched parentheses');
      }
      operators.pop(); // Remove '('
    } else if (['+', '-', '*', '/'].includes(token)) {
      // Handle unary minus - check if this is a unary minus operator
      if (token === '-' && (i === 0 || tokens[i-1] === '(' || ['+', '-', '*', '/'].includes(tokens[i-1]))) {
        // For unary minus, we need to handle it specially
        // We'll treat it as a special unary operator that will be handled during evaluation
        operators.push(token);
      } else {
        while (operators.length > 0 && 
               operators[operators.length - 1] !== '(' &&
               precedence[operators[operators.length - 1]] >= precedence[token]) {
          output.push(operators.pop());
        }
        operators.push(token);
      }
    } else {
      throw new Error(`Invalid token: ${token}`);
    }
  }

  while (operators.length > 0) {
    const op = operators.pop();
    if (op === '(' || op === ')') {
      throw new Error('Mismatched parentheses');
    }
    output.push(op);
  }

  // Evaluate postfix notation
  const stack = [];
  for (let i = 0; i < output.length; i++) {
    const token = output[i];
    if (typeof token === 'number') {
      stack.push(token);
    } else {
      // Handle unary minus in evaluation
      if (token === '-') {
        // Check if this is unary minus by checking if we have only one operand
        // This is a bit tricky - we need to look at the context
        // If we have a single element on stack, it's unary minus
        if (stack.length === 1 && i > 0 && output[i-1] === '-') {
          // This is a unary minus that was pushed to the stack
          const a = stack.pop();
          stack.push(-a);
        } else if (stack.length === 1) {
          // This is unary minus - we have one operand and we're applying minus to it
          const a = stack.pop();
          stack.push(-a);
        } else {
          // This is binary minus
          if (stack.length < 2) {
            throw new Error('Invalid expression');
          }
          const b = stack.pop();
          const a = stack.pop();
          stack.push(a - b);
        }
      } else {
        // Binary operator
        if (stack.length < 2) {
          throw new Error('Invalid expression');
        }
        const b = stack.pop();
        const a = stack.pop();

        switch (token) {
          case '+':
            stack.push(a + b);
            break;
          case '*':
            stack.push(a * b);
            break;
          case '/':
            if (b === 0) {
              throw new Error('Division by zero');
            }
            stack.push(a / b);
            break;
          default:
            throw new Error(`Invalid operator: ${token}`);
        }
      }
    }
  }

  if (stack.length !== 1) {
    throw new Error('Invalid expression');
  }

  return stack[0];
}

module.exports = { tokenize, evaluate };
