    }
    output.push(op);
  }

  // Evaluate postfix notation
  const stack = [];
  for (let i = 0; i < output.length; i++) {
    const token = output[i];
    if (typeof token === 'number') {
      stack.push(token);
    } else {
      // Handle operators
      if (token === '+' || token === '*' || token === '/') {
        if (stack.length < 2) {
          throw new Error('Invalid expression');
        }
        const b = stack.pop();
        const a = stack.pop();

        switch (token) {
